const $id=id=>$('#cs-'+id);const num=id=>{const n=Number($id(id)?.value);return Number.isFinite(n)?n:null};
function opts(el,items,placeholder){if(el)el.innerHTML='<option value="">'+esc(placeholder)+'</option>'+items.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')}
function read(id){return String($id(id)?.value||'').trim()}
function toast(msg,type='info'){const box=$('#cs-toast');if(!box)return;box.textContent=msg;box.dataset.type=type;box.classList.add('show');clearTimeout(window.__urbionToast);window.__urbionToast=setTimeout(()=>box.classList.remove('show'),2800)}
function casePayload(){return{project_name:read('project_name'),site_lat:num('lat'),site_lon:num('lon'),tod_lat:num('todlat'),tod_lon:num('todlon'),state:read('state'),pbt:read('pbt'),district:read('district'),lot_no:read('lot'),project_reference:read('project_reference'),land_use:read('landuse'),landuse:read('landuse'),development_class:read('category'),category:read('category'),activity:read('activity'),development_type:read('development'),development:read('development'),plot_ratio:num('ratio')}}
function complete(){return ['project_name','lat','lon','state','pbt','district','landuse','category','activity','development','ratio'].every(read)}
function sync(){const ids=['project_name','lat','lon','state','pbt','district','landuse','category','activity','development','ratio'];const n=ids.filter(read).length,p=Math.round(n/ids.length*100);$('#cs-ready').textContent=p+'%';$('#cs-ready-bar').style.width=p+'%';$('#cs-run').disabled=!complete()||busy;$('#cs-status-pill').textContent=busy?'PROCESSING':assessment?'ANALYSIS READY':complete()?'READY TO RUN':'CASE INCOMPLETE';$('#cs-case-title').textContent=read('project_name')||'New planning case';$('#cs-case-meta').textContent=[read('state'),read('district'),read('pbt')].filter(Boolean).join(' · ')||'Location not defined';$('#cs-run-label').textContent=lang==='bm'?'JALANKAN ANALISIS':'RUN SITE ANALYSIS'}
function cascade(){const s=$id('state'),p=$id('pbt'),d=$id('district');opts(p,PBTS[s.value]||[],lang==='bm'?'Pilih PBT':'Select PBT');opts(d,DISTRICTS[s.value]||[],lang==='bm'?'Pilih daerah':'Select district');s.onchange=()=>{opts(p,PBTS[s.value]||[],lang==='bm'?'Pilih PBT':'Select PBT');opts(d,DISTRICTS[s.value]||[],lang==='bm'?'Pilih daerah':'Select district');sync()};p.onchange=sync;d.onchange=sync}
function hierarchy(){const l=$id('landuse'),c=$id('category'),a=$id('activity');opts(l,Object.keys(LANDUSE),lang==='bm'?'Pilih guna tanah':'Select land use');l.onchange=()=>{opts(c,Object.keys(LANDUSE[l.value]||{}),lang==='bm'?'Pilih kategori':'Select category');opts(a,[],'Select activity');sync()};c.onchange=()=>{opts(a,LANDUSE[l.value]?.[c.value]||[],'Select activity');sync()};a.onchange=sync}
function caseField(label,html){return '<label class="field"><span>'+label+'</span>'+html+'</label>'}
function form(){return '<div class="case-sections"><details open><summary><span>01</span> LOCATION</summary>'+caseField('Site / Project Full Name','<input id="cs-project_name" placeholder="Project or site name" autocomplete="off">')+'<div class="two">'+caseField('Latitude','<input id="cs-lat" inputmode="decimal" placeholder="2.285000">')+caseField('Longitude','<input id="cs-lon" inputmode="decimal" placeholder="102.196000">')+'</div>'+caseField('State','<select id="cs-state"><option value="">Select state</option>'+STATES.map(s=>'<option>'+esc(s)+'</option>').join('')+'</select>')+caseField('Pihak Berkuasa Tempatan (PBT)','<select id="cs-pbt"></select>')+caseField('District / Daerah','<select id="cs-district"></select>')+'<div class="action-row"><button id="cs-pick-map" class="mini">⌖ Use Map Selection</button><button id="cs-locate" class="mini">◎ Locate me</button></div></details><details open><summary><span>02</span> SITE / PARCEL</summary><div class="two">'+caseField('Lot / UPI Reference','<input id="cs-lot" placeholder="Optional">')+caseField('Project Reference','<input id="cs-project_reference" placeholder="KM / LCP / OSC">')+'</div><div class="action-row"><button id="cs-resolve-lot" class="mini">Resolve lot</button><span id="cs-lot-status" class="inline-status">JUPEM verification remains authoritative.</span></div></details><details open><summary><span>03</span> EXISTING LAND USE</summary>'+caseField('Land Use','<select id="cs-landuse"></select>')+'</details><details open><summary><span>04</span> DEVELOPMENT PROPOSAL</summary>'+caseField('Development / Proposal Type','<select id="cs-development"><option value="">Select development / proposal</option>'+DEVELOPMENT.map(x=>'<option>'+esc(x)+'</option>').join('')+'</select>')+caseField('Development Category','<select id="cs-category"></select>')+caseField('Activity','<select id="cs-activity"></select>')+'</details><details open><summary><span>05</span> DEVELOPMENT INTENSITY</summary>'+caseField('Intensity / Plot Ratio','<input id="cs-ratio" type="number" min="0.1" step="0.1" placeholder="e.g. 4.5">')+'</details><details><summary><span>06</span> TOD / TRANSIT CONTEXT <em>OPTIONAL</em></summary>'+caseField('TOD Latitude','<input id="cs-todlat" inputmode="decimal" placeholder="Optional">')+caseField('TOD Longitude','<input id="cs-todlon" inputmode="decimal" placeholder="Optional">')+'<div class="hint">TOD distance is a screening/context measure, not an automatic statutory buffer.</div></details></div>'}
function layers(){const grouped={};LAYERS.forEach(x=>(grouped[x[2]]??=[]).push(x));return '<div class="layers-head"><div><b>MAP LAYERS</b><small>Only source-backed evidence can become active evidence.</small></div><span id="layer-count">0</span></div>'+GROUPS.map(g=>'<div class="layer-group" data-group="'+g[0]+'"><button class="group-toggle" data-group-toggle="'+g[0]+'"><span>⌄</span>'+g[1]+'</button><div class="group-body">'+(grouped[g[0]]||[]).map(x=>'<label class="fcc-layer-row" style="--layer-accent:'+(x[2]==='RISK'?'#ffbe73':x[2]==='ENVIRONMENT'?'#62dc9b':'#63dfcf')+'"><input type="checkbox" data-layer="'+x[0]+'"><span>'+esc(x[1])+'<small>'+x[3].toUpperCase()+'</small></span><input class="layer-opacity" type="range" min="20" max="100" value="70" data-opacity="'+x[0]+'" aria-label="Opacity"></label>').join('')+'</div></div>').join('')+'<div class="layer-group" data-group="TRANSPORT"><button class="group-toggle" data-group-toggle="TRANSPORT"><span>⌄</span>Transport</button><div class="group-body"><label class="fcc-layer-row" style="--layer-accent:#66b7ff"><input type="checkbox" data-layer="tod"><span>TOD / Transit<small>SPATIAL CONTEXT</small></span></label><label class="fcc-layer-row" style="--layer-accent:#7da0bf"><input type="checkbox" data-layer="roads"><span>Road Network<small>BASEMAP / CONTEXT</small></span></label></div></div><div class="legend-inline"><b>LEGEND</b><span><i class="lg site"></i>Site</span><span><i class="lg risk"></i>Risk</span><span><i class="lg eco"></i>Ecology</span><span><i class="lg parcel"></i>Parcel</span></div>'}
